export const getHiraRegionControllerListRegionsUrl = (params?: HiraRegionControllerListRegionsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/data-go-kr/hira/regions?${stringifiedParams}` : `/data-go-kr/hira/regions`
}

